gOC(){return"\u062a\u0637\u0628\u064a\u0642 \u0642\u0627\u0631\u0626 \u0627\u0644\u0643\u062a\u0628"},
gV2(){return"Verse Flow\n\u062a\u062c\u0631\u0628\u0629 \u0642\u0631\u0627\u0621\u0629 \u0639\u0635\u0631\u064a\u0629 \ud83d\udcda"},
gOD(){return"\u062a\u0635\u0645\u064a\u0645 \u0623\u0646\u064a\u0642 \u0648\u0628\u0633\u064a\u0637 \u0644\u062a\u0637\u0628\u064a\u0642 \u0642\u0627\u0631\u0626 \u0643\u062a\u0628 \u064a\u0631\u0643\u0632 \u0639\u0644\u0649 \u0631\u0627\u062d\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0648\u0633\u0647\u0648\u0644\u0629 \u0627\u0644\u0642\u0631\u0627\u0621\u0629. \u064a\u062a\u0645\u064a\u0632 \u0628\u0648\u0627\u062c\u0647\u0629 \u062a\u0648\u0641\u0631 \u0627\u0644\u062a\u062d\u0643\u0645 \u0641\u064a \u062d\u062c\u0645 \u0627\u0644\u0646\u0635\u060c \u0627\u0644\u0648\u0636\u0639 \u0627\u0644\u0644\u064a\u0644\u064a/\u0627\u0644\u0646\u0647\u0627\u0631\u064a\u060c \u0627\u0646\u062a\u0642\u0627\u0644\u0627\u062a \u0633\u0644\u0633\u0629 \u0628\u064a\u0646 \u0627\u0644\u0635\u0641\u062d\u0627\u062a\u060c \u0648\u062a\u0635\u0645\u064a\u0645 \u0645\u0643\u062a\u0628\u0629 \u0623\u0646\u064a\u0642."},
