gfs(){return"\u0627\u0644\u062a\u0627\u0644\u064a"},
gUE(){return"\u062a\u0637\u0628\u064a\u0642 \u0627\u0644\u062a\u062f\u0627\u0648\u0644"},
gUG(){return"\u0630\u0643\u064a \u0648\u0628\u0633\u064a\u0637\n\u0645\u0646\u0635\u0629 \u062a\u062f\u0627\u0648\u0644 \u0627\u0644\u0623\u0633\u0647\u0645 \ud83d\udcc8"},
gUF(){return"\u062a\u0635\u0645\u064a\u0645 \u0648\u0627\u062c\u0647\u0629 \u0646\u0638\u064a\u0641 \u0648\u0628\u0633\u064a\u0637 \u0644\u062a\u0637\u0628\u064a\u0642 \u062a\u062f\u0627\u0648\u0644 \u0627\u0644\u0623\u0633\u0647\u0645 \u0648\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0645\u062d\u0627\u0641\u0638 \u0627\u0644\u0627\u0633\u062a\u062b\u0645\u0627\u0631\u064a\u0629. \u064a\u0631\u0643\u0632 \u0639\u0644\u0649 \u0639\u0631\u0636 \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0633\u0648\u0642 \u0644\u062d\u0638\u064a\u064b\u0627\u060c \u0645\u062e\u0637\u0637\u0627\u062a \u062a\u0641\u0627\u0639\u0644\u064a\u0629\u060c \u0642\u0648\u0627\u0626\u0645 \u0645\u062a\u0627\u0628\u0639\u0629\u060c \u0648\u062a\u062c\u0631\u0628\u0629 \u062a\u0646\u0642\u0644 \u0633\u0644\u0633\u0629 \u062a\u062e\u062f\u0645 \u0627\u0644\u0645\u0628\u062a\u062f\u0626\u064a\u0646 \u0648\u0627\u0644\u0645\u062d\u062a\u0631\u0641\u064a\u0646."},
