gT1(){return"\u062e\u062f\u0645\u0627\u062a \u0630\u0643\u064a\u0629\n\u0644\u0644\u0645\u062a\u0642\u0627\u0639\u062f\u064a\u0646 \u0627\u0644\u0641\u0644\u0633\u0637\u064a\u0646\u064a\u064a\u0646 \ud83c\uddf5\ud83c\uddf8"},
gT0(){return"\u062a\u0635\u0645\u064a\u0645 \u0648\u0627\u062c\u0647\u0629 \u0648\u0627\u0636\u062d\u0629 \u0648\u0633\u0647\u0644\u0629 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0644\u062a\u0637\u0628\u064a\u0642 \u0647\u064a\u0626\u0629 \u0627\u0644\u062a\u0642\u0627\u0639\u062f \u0627\u0644\u0641\u0644\u0633\u0637\u064a\u0646\u064a\u0629. \u064a\u062a\u064a\u062d \u0644\u0644\u0645\u062a\u0642\u0627\u0639\u062f\u064a\u0646 \u0639\u0631\u0636 \u062a\u0641\u0627\u0635\u064a\u0644 \u0627\u0644\u0645\u0639\u0627\u0634 \u0627\u0644\u0634\u0647\u0631\u064a\u060c \u0637\u0644\u0628 \u0627\u0644\u0648\u062b\u0627\u0626\u0642 \u0627\u0644\u0631\u0633\u0645\u064a\u0629\u060c \u062a\u062a\u0628\u0639 \u0633\u0646\u0648\u0627\u062a \u0627\u0644\u062e\u062f\u0645\u0629\u060c \u0648\u0627\u0633\u062a\u0642\u0628\u0627\u0644 \u0627\u0644\u062a\u062d\u062f\u064a\u062b\u0627\u062a \u0645\u0646 \u0627\u0644\u0647\u064a\u0626\u0629."},
gQw(){return"\u062a\u062c\u0631\u0628\u0629 \u062d\u062c\u0632 \u0627\u0644\u0641\u0639\u0627\u0644\u064a\u0627\u062a"},
gOZ(){return"\u062a\u0635\u0645\u064a\u0645 \u0646\u0638\u064a\u0641"},
gQm(){return"\u0644\u0648\u062d\u0629 \u0623\u0644\u0648\u0627\u0646 \u0623\u0646\u064a\u0642\u0629"},
gRg(){return"\u062a\u0637\u0628\u064a\u0642 Happy Season"},
