gRh(){return"\u062a\u0635\u0645\u064a\u0645 \u0648\u0627\u062c\u0647\u0629 \u0623\u0646\u064a\u0642 \u0648\u0633\u0647\u0644 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0644\u062a\u0637\u0628\u064a\u0642 \u062d\u062c\u0632 \u0642\u0627\u0639\u0627\u062a \u0627\u0644\u0623\u0639\u0631\u0627\u0633 \u0648\u0627\u0644\u0641\u0639\u0627\u0644\u064a\u0627\u062a. \u064a\u0633\u0627\u0639\u062f Happy Season \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0639\u0644\u0649 \u0627\u0633\u062a\u0643\u0634\u0627\u0641 \u0627\u0644\u0642\u0627\u0639\u0627\u062a\u060c \u0645\u0642\u0627\u0631\u0646\u062a\u0647\u0627\u060c \u0648\u062d\u062c\u0632\u0647\u0627 \u0628\u0633\u0647\u0648\u0644\u0629."},
gPC(){return"\u0637\u0627\u0628\u0639 \u062b\u0642\u0627\u0641\u064a"},
gSG(){return"\u062a\u0635\u0645\u064a\u0645 \u0644\u0645\u0646\u0638\u0645\u0627\u062a \u063a\u064a\u0631 \u0631\u0628\u062d\u064a\u0629"},
gOX(){return"\u0648\u0627\u062c\u0647\u0629 \u0645\u0646\u0627\u0633\u0628\u0629 \u0644\u0644\u0623\u0637\u0641\u0627\u0644"},
gSA(){return"\u0645\u0648\u0642\u0639 \u062c\u0645\u0639\u064a\u0629 \u0646\u0648\u0649"},
gSC(){return"\u0642\u0644\u0648\u0628 \u0635\u063a\u064a\u0631\u0629\n\u0648\u062c\u0630\u0648\u0631 \u0639\u0645\u064a\u0642\u0629"},
gSB(){return"\u062a\u0635\u0645\u064a\u0645 \u0648\u0627\u062c\u0647\u0629 \u0645\u0648\u0642\u0639 \u062f\u0627\u0641\u0626 \u0648\u062c\u0630\u0627\u0628 \u0644\u0645\u0646\u0638\u0645\u0629 \u063a\u064a\u0631 \u0631\u0628\u062d\u064a\u0629 \u0645\u0643\u0631\u0633\u0629 \u0644\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0644\u062a\u0631\u0627\u062b \u0627\u0644\u062b\u0642\u0627\u0641\u064a \u0648\u062f\u0639\u0645 \u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0623\u0637\u0641\u0627\u0644."},
