gPw(){return"\u062a\u0635\u0645\u064a\u0645 \u0634\u0631\u0643\u0627\u062a"},
gGb(){return"GLOBAL BUILDERS"},
gGd(){return"\u0627\u0644\u0628\u0646\u0627\u0621 \u062d\u0648\u0644 \u0627\u0644\u0639\u0627\u0644\u0645"},
gGc(){return"\u062a\u0635\u0645\u064a\u0645 \u0635\u0641\u062d\u0629 \u0647\u0628\u0648\u0637 \u062d\u062f\u064a\u062b\u0629 \u0648\u0627\u062d\u062a\u0631\u0627\u0641\u064a\u0629 \u0644\u0634\u0631\u0643\u0629 \u0625\u0646\u0634\u0627\u0621\u0627\u062a \u0639\u0627\u0644\u0645\u064a\u0629. \u064a\u062a\u0645\u064a\u0632 \u0628\u062e\u0637\u0648\u0637 \u0642\u0648\u064a\u0629\u060c \u062a\u0633\u0644\u0633\u0644 \u0628\u0635\u0631\u064a \u0648\u0627\u0636\u062d\u060c \u0639\u0646\u0627\u0635\u0631 \u062a\u0639\u0632\u0632 \u0627\u0644\u062b\u0642\u0629\u060c \u0648\u0623\u0642\u0633\u0627\u0645 \u062a\u0639\u0631\u0636 \u0627\u0644\u062e\u062f\u0645\u0627\u062a."},
gPF(){return"\u062a\u0635\u0645\u064a\u0645 \u0644\u0648\u062d\u0629 \u062a\u062d\u0643\u0645"},
